ISNULL.examples.default-value.sql:
DECLARE @Reader TABLE (ReaderId int, NickName nvarchar(20));
INSERT INTO @Reader VALUES (1, NULL);
SELECT ISNULL(NickName, N'(not set)') FROM @Reader   -- '(not set)'

NULLIF.examples.safe-division-column.sql:
DECLARE @Copy TABLE (CopyNo int, LoanCount int);
INSERT INTO @Copy VALUES (1, 0);
SELECT CopyNo, 100.0 / NULLIF(LoanCount, 0) AS AvgLoad FROM @Copy   -- NULL, no division-by-zero error

IIF.examples.with-table.sql:
DECLARE @Copy TABLE (CopyNo int, Status tinyint);
INSERT INTO @Copy VALUES (1, 1), (2, 0);
SELECT CopyNo, IIF(Status = 1, N'checked out', N'on shelf') FROM @Copy ORDER BY CopyNo   -- 1: checked out; 2: on shelf

STRING_AGG.examples.ignores-null.sql:
DECLARE @Copy TABLE (CopyNo varchar(10));
INSERT INTO @Copy VALUES ('A01'), (NULL), ('A02');
SELECT STRING_AGG(CopyNo, ', ') WITHIN GROUP (ORDER BY CopyNo) FROM @Copy   -- 'A01, A02' (NULL is skipped, no leftover separator)

STRING_AGG.examples.group-by-branch.sql:
DECLARE @Copy TABLE (BranchId int, CopyNo varchar(10));
INSERT INTO @Copy VALUES (1, 'A01'), (1, 'A02'), (2, 'B01');
SELECT BranchId, STRING_AGG(CopyNo, ', ') WITHIN GROUP (ORDER BY CopyNo)
FROM @Copy GROUP BY BranchId ORDER BY BranchId   -- 1: 'A01, A02'; 2: 'B01'

ROW_NUMBER.examples.vs-rank-dense-rank.sql:
DECLARE @t TABLE (Id int, D date);
INSERT INTO @t VALUES (1,'2026-01-01'),(2,'2026-01-01'),(3,'2026-01-02'),(4,'2026-01-03');
SELECT Id,
       ROW_NUMBER() OVER (ORDER BY D) AS RowNum,
       RANK()       OVER (ORDER BY D) AS Rnk,
       DENSE_RANK() OVER (ORDER BY D) AS DenseRnk
FROM @t ORDER BY D;
-- First two rows tie: RowNum gets 1, 2; Rnk both 1; DenseRnk both 1;
-- Third row: Rnk jumps to 3, DenseRnk only 2; fourth row: Rnk=4, DenseRnk=3

DENSE_RANK.examples.vs-row-number-rank.sql:
DECLARE @t TABLE (Id int, D date);
INSERT INTO @t VALUES (1,'2026-01-01'),(2,'2026-01-01'),(3,'2026-01-02'),(4,'2026-01-03');
SELECT Id,
       ROW_NUMBER() OVER (ORDER BY D) AS RowNum,
       RANK()       OVER (ORDER BY D) AS Rnk,
       DENSE_RANK() OVER (ORDER BY D) AS DenseRnk
FROM @t ORDER BY D;
-- First two rows tie: DenseRnk both 1; third row is 2 (no gap); that row's Rnk is 3

RANK.examples.vs-row-number-dense-rank.sql:
DECLARE @t TABLE (Id int, D date);
INSERT INTO @t VALUES (1,'2026-01-01'),(2,'2026-01-01'),(3,'2026-01-02'),(4,'2026-01-03');
SELECT Id,
       ROW_NUMBER() OVER (ORDER BY D) AS RowNum,
