-- First two rows tie: Rnk both 1; third row jumps to 3 (skipping 2); fourth row is 4

STUFF.examples.legacy-concat-vs-string-agg.sql:
DECLARE @Copy TABLE (CopyNo varchar(10));
INSERT INTO @Copy VALUES ('A01'), ('A02'), ('A03');
SELECT STUFF((
  SELECT ', ' + CopyNo FROM @Copy ORDER BY CopyNo FOR XML PATH('')
), 1, 2, '')   -- 'A01, A02, A03'; STRING_AGG (SQL Server 2017+) is more direct

OBJECT_ID.examples.temp-table.sql:
CREATE TABLE #t (Id int);
SELECT OBJECT_ID('#t') AS NotFound, OBJECT_ID('tempdb..#t') AS Found;
DROP TABLE #t;
-- NotFound is NULL (looked up in the current database); Found has a value (needs tempdb..)

SCOPE_IDENTITY.examples.trigger-scenario.sql:
CREATE TABLE dbo.Lib_Tag (Id int IDENTITY, Name nvarchar(50));
CREATE TABLE dbo.Lib_TagLog (Id int IDENTITY(100,1), TagId int);
GO
CREATE TRIGGER trg_Lib_Tag_Log ON dbo.Lib_Tag AFTER INSERT AS
  INSERT INTO dbo.Lib_TagLog (TagId) SELECT Id FROM inserted;
GO
INSERT INTO dbo.Lib_Tag (Name) VALUES ('Fiction');
SELECT SCOPE_IDENTITY() AS ScopeId, @@IDENTITY AS GlobalId, IDENT_CURRENT('dbo.Lib_Tag') AS CurrentId;
-- ScopeId=1 (Lib_Tag's row); GlobalId=100 (overwritten by Lib_TagLog's identity); CurrentId=1 (only looks at Lib_Tag)
DROP TABLE dbo.Lib_Tag; DROP TABLE dbo.Lib_TagLog;

DATEDIFF_BIG.examples.elapsed-minutes.sql:
DECLARE @Loan TABLE (LoanId int, LoanDate datetime2, ReturnDate datetime2);
INSERT INTO @Loan VALUES (1, '2026-09-01 09:00:00', '2026-09-08 09:00:00');
SELECT DATEDIFF_BIG(MINUTE, LoanDate, ReturnDate) FROM @Loan   -- 10080 (7 days)
